  float t = cc_time.x;
  vec3 L = normalize(vec3(-0.45, 0.55, 0.8));
  vec3 H = normalize(L + vec3(0.0, 0.0, 1.0));
  float fres = pow(1.0 - z, 3.0);
  float breathe = 1.0 + gB.w * 0.35 * sin(t * 1.6);
