  { vec2 q = rot2(-0.6) * p;
    glow += vec3(1.0) * smoothstep(0.26, 0.0, abs(q.y - 0.42)) * smoothstep(0.9, 0.2, r) * gA.w; }
  { vec2 hp = rot2(t * gD.z) * p;
    glow += vec3(1.0) * pow(max(dot(vec3(hp, z), H), 0.0), 120.0) * gB.x * 1.5; }
  { vec2 sd = normalize(vec2(0.6, 1.0)); float pos = fract(t * gD.x) * 2.4 - 1.2;
    glow += vec3(1.0) * smoothstep(0.14, 0.0, abs(dot(p, sd) - pos)) * smoothstep(1.0, 0.3, r) * gB.y; }
