    float h2 = hash21(floor(sp * dens * 3.0) + 7.1);
    glow += vec3(1.0, 0.95, 0.7) * step(0.93, h2) * (0.5 + 0.5*sin(t*8.0 + h2*TAU)) * gC.w;
  }
  glow *= breathe;
  glow = clamp(glow, 0.0, 1.0);
  vec3 col = 1.0 - (1.0 - base) * (1.0 - glow);
  col = mix(base, col, gD.w);
  vec4 o = vec4(col, tex.a);
  o *= color;
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

